for (const item of $input.all()) {
  const text = item.json.query || "";

  const agencyMatch = text.match(/agency_id:([a-f0-9-]{36})/i);
  item.json.extracted_agency_id = agencyMatch ? agencyMatch[1] : "default_session";

  const conversationMatch = text.match(/conversation_id:([a-f0-9-]{36})/i);
  item.json.extracted_conversation_id = conversationMatch ? conversationMatch[1] : "default_conversation";

  const urlMatch = text.match(/https?:\/\/[^\s]+/i);
  item.json.extracted_url = urlMatch ? urlMatch[0].replace(/[.,;:]+$/, "") : "";

  let clean = text
    .replace(/agency_id:[a-f0-9-]{36}/ig, "")
    .replace(/conversation_id:[a-f0-9-]{36}/ig, "")
    .replace(/https?:\/\/[^\s]+/ig, "")
    .replace(/\s+/g, " ")
    .trim();
  if (clean.length < 3) clean = (text.trim() || "propiedad");
  item.json.clean_query = clean;
}

return $input.all();

const base = $('extraer_agency_id').first().json;
const j = $json || {};
const scraped = (j && j.sujeto) ? j : null;
let cq = base.clean_query || 'propiedad';
let extra = '';
const clean = (t) => (t == null ? '' : String(t)).toLowerCase().split("'").join('').split('"').join('').split(';').join('').split(' ').filter(Boolean).join(' ');
let ref = { ref_from_link: false, ref_price: '', ref_currency: '', ref_rooms: '', ref_zona: '', ref_addr: '' };
if (base.extracted_url && scraped) {
  const s = scraped.sujeto || {};
  const amen = s.amenidades ? Object.keys(s.amenidades).join(', ') : '';
  const parts = [s.tipo_propiedad, s.barrio, s.direccion, (s.dormitorios != null ? s.dormitorios + ' dormitorios' : ''), (s.m2_cubiertos ? s.m2_cubiertos + ' m2' : ''), amen];
  cq = parts.filter(Boolean).join(' ').trim() || cq;
  extra = '\n\n[DATOS DE LA PROPIEDAD DEL LINK - para identificarla en el stock; el precio es SOLO referencia, NO presupuesto]: ' + JSON.stringify(scraped);
  ref.ref_from_link = true;
  ref.ref_price = (scraped.precio != null && !isNaN(Number(scraped.precio))) ? String(Math.round(Number(scraped.precio))) : '';
  ref.ref_currency = (clean(scraped.moneda).toUpperCase()) || 'USD';
  ref.ref_rooms = (s.dormitorios != null && !isNaN(Number(s.dormitorios))) ? String(Number(s.dormitorios) + 1) : '';
  ref.ref_zona = clean(s.barrio);
  ref.ref_addr = clean(s.direccion);
}
return [{ json: Object.assign({}, base, { clean_query: cq, agent_extra: extra, scraped: scraped || null }, ref), pairedItem: { item: 0 } }];

